window.POETRY_REGISTER("v5-extra-11-9-0-2f35c8e63dca.js",{"poems":[[2838,2],[11269,2],[51879,2],[52094,2],[52291,2],[53586,2],[54061,2],[54505,2],[54563,2],[55244,2],[56616,2],[57059,2],[57078,2],[57092,2],[58716,2],[94286,7],[104970,7],[105084,7],[109551,7],[113121,7],[115935,7],[132199,7],[136230,7],[142080,7],[153039,7],[193734,7],[204959,7],[223648,7],[225267,7],[230809,7],[233445,7],[236151,7],[250736,7],[251671,7],[265404,7],[265447,7],[267711,7],[267739,7],[268143,7],[270369,7],[285959,7],[287932,7],[289440,7],[295323,7],[297987,7],[299339,7],[299344,7],[299357,7],[301584,7],[304219,7],[310413,7],[312484,7],[324758,7],[325718,7],[331771,7],[335422,9],[340214,9],[342621,9],[346511,9],[350201,9],[350997,9],[351009,9],[351024,9],[354093,9],[359687,9],[360157,9],[361702,9],[364000,9],[365412,9],[368131,10],[368167,10],[368191,10],[368203,10],[368392,10],[368397,10],[371067,10],[371145,10],[374756,10],[374760,10],[375195,10],[375207,10],[375231,10],[375295,10],[375298,10],[375300,10],[375310,10],[380145,10],[382253,0],[391461,13],[396686,13],[398986,8],[409005,8],[410318,8],[422361,8],[422419,8],[425741,8],[425930,8],[433080,8],[438276,8],[438292,8],[442436,8],[451828,8],[451830,8],[466223,8],[472649,8],[473644,8],[473778,8],[477879,8],[483178,8],[488526,8],[495499,8],[501755,8],[504999,8],[505005,8],[506011,8],[532524,8],[540737,8],[545954,8],[551652,8],[554951,8],[581799,8],[581832,8],[589675,8],[589894,8],[594112,8],[596211,8],[596213,8],[599666,8],[624750,8],[625634,8],[631345,8],[648443,16],[648687,16],[650074,5],[651018,5],[651666,5],[651667,5],[652443,5],[652758,5],[652778,5],[657023,5],[660248,5],[660484,5],[660776,5],[660791,5],[662131,5],[663418,5],[668900,5],[669214,5],[669380,5],[669893,5],[671605,5],[672139,5],[672993,5],[680600,5],[681117,5],[681338,5],[681637,5],[681762,5],[685297,5],[690201,5],[693930,5],[706935,5],[706948,5],[708914,5],[711281,5],[722750,5],[740495,20],[742045,22]],"pairs":[["一百二十凤皇罗列含明珠","下有锦铺翠被之粲烂",0],["一百二十凤凰罗列含明珠","下有锦铺翠被之粲烂",1],["王勃并未担任过这类官职","整王使君当另有其人",2],["叫他做了僧官或随从官员","但不幸被吐蕃所俘虏",3],["山上在圣武天皇天平之世","此文为山上末年之作",4],["及出洞已为明洪武十二年","则此诗显出明人附会",5],["今将童氏未录者全部录出","合计共得诗四十二首",6],["据敦煌残卷伯三六一九补","当作于天宝十一载秋",7],["戴征士戴征君当为同一人","因知王绶与李端同时",8],["清嘉庆六年三月二十七日","法忍寺天空阁毁于火",9],["右题云黄石公以授张良者","按其书杂占行军吉凶",10],["集句诗后附载和诗诸公云","高峰妙法嗣布衲雍公",11],["此诗题下署吴越国王钱俶","末附嘉泰壬戌宗晓跋",12],["以上三颂皆为参德韶后作","德韶卒于吴越纳土前",13],["以孟郊诗与吴棫所录对校","二十字中有八字不同",14],["落亦不学飞燕皇后回风舞","此意又笑麻姑与王母",15],["此人朅来就彼剜剔归上天","所以此石拆𠠦不复合",16],["言君所部之内此物尤奇绝","后复寄书劝我当饵之",17],["鸟兽蕃而走集兮虞不能知","因高错事兮道此跻陛",18],["今既累百至千未免广搜觅","古人载书兼两惧猜谤",19],["又恐一朝舍此愚意无以适","碑乎誓将蓄汝永吾好",19],["冒霜停雪拂景云而萦惠风","吾曹对此但欲适清乐",20],["限以龙王大孤彭浪之险阻","鄱阳彭蠡淮海之波涛",21],["高荷为盖兮倚芙蓉以当伎","霜清水寒兮舟著平沙",22],["黄闵之记盘瓠行迹今依然","高辛氏时北有大戎寇",23],["少壮几时兮老冉冉其相仍","展转反侧兮从夜达明",24],["今晨忽被蛮烟蜑雾埋其高","安得万里飘风一吹散",25],["束缚冠屦如以桎梏置我旁","安得天风吹上雪山顶",26],["亦有霓旌素节日夜朝京师","又疑春秋战罢两蜗角",27],["问谁作此狡狯变化惊盲聋","乃是清江江上盘园翁",28],["匪若人之良茂兮吾将奚頼","芹波摇日兮槐阴转午",29],["怨飘风之怒狂兮害于物理","猨狖啸侣兮上获我冠",30],["常恐失之君山湖上之风波","梓潼使君之赠尚尔耳",31],["临春结绮望仙三阁俱下头","杯埦块潜培𪣻而已矣",32],["柽萝密丛灌盘纡兮杳藏日","嶙峋凿落兮蕫茏回复",33],["眷令长之远虑兮不间雨旸","晴日当空兮余备不忘",34],["乃肯折节作赋遗恨无纤毫","诗雄赋老不入世俗眼",35],["太守归我皇极天子大父母","愿见太平万古万万古",36],["如银河自天争泻而竞注兮","砅雷溅雪隠现穿林幽",37],["只管将鼻孔东边嗅西边嗅","自己鼻尖上有一点粪",38],["反言挺而茂者肥瘠贵得中","吁嗟九原相如不可作",39],["幔亭结云霞兮彩桥跨虹霓","欲访仙迹兮搜剔地灵",40],["来与十有四叶天子苏寰瀛","春生秋杀造化功始备",41],["无由登山临水兮与鸥鹭盟","北风吹袂兮又将之荆",42],["洒墨我别兮人间父子之情","我枯如腊兮涕更纵横",43],["倒影茅屋但觉烨弈光荧荧","我闻昔者王家有宝镜",44],["碧光绛气连属日月含天庭","又闻西方圣者释迦子",44],["三千世界合作一色白月明","今之奇光异色无乃是",44],["袖出异书光芒与我易相射","平生但识羲孔元之元",45],["病骨嵚𡼭会当化为原上骼","拟从诸君豫乞石一方",46],["云何却以后天混入先天图","嗟吁平生粗知读周易",47],["日渐月渍学子饱隽诗书膏","意欲国为邹鲁家稷皋",48],["浩浩汤汤流溢江湖无著处","岂不胜越人歌来何暮",49],["不尔羁臣逐客对月翻凄咽","呜呼身在雪岭盘车图",50],["劝君不用六十四卦推天星","但愿得君肘后之丹经",51],["中秘幽奇世人未见犹未闻","混沌乍开始自大唐国",52],["古泉眼中见有相似二君不","我亦有耳但愿听松风",53],["吾不愿子以之奏赋如枚邹","愿子提携与之登瀛洲",54],["一个干骷髅顶戴着十分罪","为儿女使尽了拖刀计",55],["风沙暑雨亦复不厌能留连","我为道人写真已太逼",56],["客卿如灵俾我慧悟加诸前","待渠宣力恢复旧封域",57],["我怀伊人兮渺不知其所之","采采兰若兮充尔佩袆",58],["胡为尚滞禹门点额之龙鱼","譬犹卞和白壁隋侯珠",59],["未遇具眼宁同瓦砾迷榛墟","君文璀璨新出之珊瑚",59],["阿奶喜欢一一为孙加啖歠","便出泄泻腑脏如雷奔",60],["翩然归卧计筹峰下通玄馆","日听松风不异大韶乐",61],["问其日给虾蟹小鲜日三炊","有时大鱼入网即沽酒",62],["知有神物拥护终是阴为惩","不然日围千里不一蓄",63],["彼世之人兮孰能遗我以忧","虽欲从我兮其路无由",64],["茧袍鸠杖高步时得追文同","居旁万竹固已具胸次",65],["仕止久速兮舍圣人将安求","清风一丝兮岂为名钩",66],["扶义而西取天下者以三尺","君看项王重瞳舜重瞳",67],["狐狸饱而跳踉兮腐胔纵横","藜藿出户兮室无哭声",68],["皇保下人兮曷椓丧而极斯","乐人之死兮职魃所为",68],["耗贼大和兮遏玄泽于既施","朋殃友厉兮出入敖娭",68],["害戕屏绝兮鬯嘉生于百龄","磔弃妖膂兮沉溺清泠",68],["圣人登之天下小似东龟蒙","夜闻巨灵荡蹋西华峰",69],["食君之禄而弗与国同存亡","呜呼节妇之德不可量",70],["尚须皮毛解剥净洗五藏腥","如何三经一笔乃尔灵",71],["胸中元有邺侯三万牙签书","曩执金陵南端之白简",72],["采楟花以为食兮食不下咽","嗟儿天父兮天胡有偏",73],["自言昨夜梦游海上天梯山","天梯之山三万八千丈",74],["洗涤盘古肠胃心肾肝肺脾","却取女娲所抟黄土块",75],["周伯老子无所藏匿其祥灾","老胡不识金木水火土",76],["厓厓坐得四肢百骨如干柴","所以天地鬼神不怪怒",76],["嗟此神物夐然独立而无邻","呜呼神物为物固有神",77],["其体浑沦绝侣大造无痕迹","其字遒逸宛是篆与科",78],["扶竖正直兮不茹吐其柔刚","鸾凤远举兮枭獍云亡",79],["劝以日饮毋苛斗鸡走狗嘻","不则利剑刺君君莫支",80],["久安长治安得万岁而千秋","君不见沙丘鲍乌江猴",81],["剡蒿以为梁兮削菌以居楹","匠石却走兮工垂拊膺",82],["指玉以为石兮削方以为规","天不可问兮神不可咨",83],["剪薙杞梓兮索灌莽以取木","捕猫乳鼠兮佥以为仁",84],["呜呼哀哉兮尔何生于此时","周公巳矣兮吾能不悲",85],["一一秀出紫金翠羽之华芝","中有少室八百六十丈",86],["今日何日兮得与王子同舟","蒙羞被好兮不訾诟耻",87],["不尔羁臣逐客对月翻凄咽","呜呼身在雪岭盘车图",88],["我不爱尔绝汉排云之健翼","爱尔秋来意气各有适",89],["嗟尔龙兮顺济斯民千万秋","龙亦永赫厥灵于此州",90],["未闻太行王屋曾为愚公移","天地生我死我自有处",91],["吁嗟兹山有径不与终南通","士将避世往往游其中",92],["驰入边城搴取五丈之长旗","又不能挟大弓乘青骊",93],["气如望之入见堂堂谢挟持","豁如晋公掀淖出泥涂",94],["照见种种群生臭腐兼旖旎","岂无牡丹妆点春富贵",95],["想君胸中自有五城十二楼","安用崿舞峦飞之突兀",96],["予敢爱生兮致淑德于无旌","呜呼兮已舆尸于故国",97],["才登八旬直至百岁寿未穷","荣膺恩命更进夫人封",98],["所以惟爱戛然仙骥之长鸣","聆之弗厌危坐到更阑",99],["蹇予山中之人兮猿狖与居","怅独处此兮情莫能娱",100],["仁有杀身而成兮身今在兹","毁以易亲死兮又何惜",101],["龙周于天兮挟公子以凌云","翁寿而燕兮捷书在阍",102],["呜呼安得飞廉奉职屏翳趋","顿使和风澍雨弥八区",103],["下抱太空各垂文光密星象","晓日波平如熨横素罗",104],["前元馀属负固北庭保其宅","团结党类以俟我衅隙",105],["男儿有身睥睨六合追巢由","不然淋漓大白扫椽笔",106],["飘如乘虹驾鹤飞出天地间","但闻长风飒飒万里至",107],["山中之路不知何年始开辟","羊肠萦纡孰得以形状",108],["锟铻赤堇之产兮百炼益刚","猗嗟豸冠兮生者为殇",109],["我哀豸冠兮重珰谋之不臧","冠发上指兮夜何时明",109],["恨不真有此桃来侑长生卮","吾闻严子为政仁且明",110],["不独寒饥迫我为我涕沾裳","安得男耕女织无捕租",111],["复有长江之水朝夕相撞舂","其间岁月不知几千百",112],["又东千里行绕凤凰之高台","南徐望海只尺是青天",113],["报以诸福更百千岁如一时","贤甥地官祝在图与诗",114],["神禹乃梦玄夷使者来相逢","朱陵宝洞九向而九背",115],["彼浮丘之何代兮于谁而逢","吹笙玄圃兮驾鹤溟蒙",116],["今日何日兮载王子于中流","含情欲诉兮怀羞复止",117],["上有河图北斗八卦之方位","下铭忠肝义胆两行字",118],["既无翰林二字来使村落惊","自嘲自笑郎州行正事",119],["砥石奔流直到东海不复回","此时英风浩然洒六合",120],["摧轮怪石硱磳磊落而成堆","太行之高且险也如此",120],["南有峨眉凌空夤缘鸟道窄","群山合沓险远不可穷",121],["攒峦架壑阴森蓊郁起烟雾","野花涧草乱杂难具名",121],["发源岷麓东注沧溟无底谷","深山幽壑溪涧千万支",121],["我之怀矣与泉偕滴而无声","山下出泉兮于彼幽谷",122],["要补山龙华虫黼黻之华裾","今日刍荛有语烦听取",123],["誓良人之不从兮孤曷与存","瞻彼中林兮豺虎纵横",124],["太祖以来食尽多少官仓米","一朝缓急不得分寸力",125],["汝之生也不似彗帚排青苍","安能截作笙箫来凤凰",126],["达者玩世生死造化昧端倪","乃今独解众悟理则那",127],["神禹乃梦玄夷使者来相逢","朱陵宝洞九向而九背",128],["前元馀属负固北庭保其宅","团结党类以俟我衅隙",129],["彼浮丘之何代兮于谁而逢","吹笙玄圃兮驾鹤溟蒙",130],["往者不可及兮来者不可待","悠悠苍天兮莫我振理",131],["往者不可及兮来者不可待","悠悠苍天兮莫我振理",132],["平稳稳的乾坤又起了争端","造作了那枪刀和弓箭",133],["满朝里咬文嚼字使干了口","铁桶似的乾坤半边塌",133],["何为使我漂流天南海北陬","日与腐儒小子论诗书",134],["鼎内安庆无援已在掌握间","江淮大局进退在一战",135],["何况能谋能战平生无败创","所恨仓卒不待一二载",135],["车后遗弃粱肉庑下堆黄金","阿史社尔行军无卧具",136],["将军命之携印以出归帝里","其奈贼人拥蜂更屯蚁",137],["依稀绝壑千树万树松风清","始知中郎焦尾疑附会",138],["呜呼菊兮托根幸在幽人屋","一任户外狂飙三日足",139],["或疑入定真容仿佛亲见之","不然调铅杀粉能尔为",140],["其为穆王鼍梁高架之奇工","不然何其宛转三百尺",141],["而于学道之人一一若无预","儒林将相史策空分科",142],["其间道里岁月得无多迁延","又闻帝阍九重位高拱",143],["胡乃断断向我摇尾而乞怜","言讫掉头不复顾翩然",143],["但见野花纤草历乱愁人心","君不见澄心堂净居室",144],["无能为役祇录东郊瘦马诗","吾闻米芾奉敕作大字",145],["中有十万八千兵民鬼声苦","舟人告余云是新战场",146],["楼上道人老方嗜酒同疏放","万千气象昼夜一栏前",147],["又似仙山风雨离合来罗浮","纵横变幻缥缈不可测",148],["远自琉球日本一发之中来","风声水声倒卷石楼动",149],["不然道子嘉陵山水图一幅","那知腾掷造化割阴阳",150],["男儿不得挂剑万里博封侯","也须东插泰山日观脚",150],["但见土花惨澹面冷无颜色","似有无限烦冤诉不得",151],["何况有人手持造化之橐钥","能以阴阳为炭炼五金",152],["其中更有西山鹤山来同盟","八百载后归之乐安孙",153],["亦不愿作朱明洞主秦仙人","但愿珠江排日泛花舫",154],["著我飞楼缥缈独立之吟身","少陵太白看月不到处",155],["中有蛮姬十队并作天魔舞","东音西音四起声咿嚘",155],["罗浮一点乃在南岭之南隅","神禹伯益导焚所未到",156],["儒冠复戴奄奄欲绝宁吾衷","已无一时豪杰可摧倒",157],["凤虽不至吾仍种竹栽梧桐","梦中忽见海上故亲友",157],["屹然屏蔽广州东路之上游","东坡自言寄家罗浮下",158],["更细数盟言织就回文重写","那便得眼前玉人如画",159],["但闻凄凄切切野哭泪汪汪","是时我心抑郁若王郎",160],["那如此榕近我几塌青蒙冥","或言榕松篆隶字本通",161],["上有琼楼玉宇高处天风寒","中间一人冕旒拟王者",162],["乌知仇人不死翻贻家国忧","臣等闻变行叹复坐愁",163],["愿为天下人子大声而疾呼","与其风尘奔走富且贵",164],["彼荼此荠谁其主者纷安排","不识我于禄籍注何等",165],["我闻拘弥之国有变昼之草","岂知兴州直北滦河东",166],["且道未有介山之前复谁主","山深地古自是有神物",167],["吁嗟道之不行兮垂翅东归","皇之不断兮劳身西飞",168]]});
